def minimum_k_bit_flips(nums, k):
 active=answer=0;started=[0]*len(nums)
 for i,bit in enumerate(nums):
  if i>=k:active^=started[i-k]
  if bit==active:
   if i+k>len(nums):return -1
   started[i]=1;active^=1;answer+=1
 return answer

